#### depth first

```cpp
#include <vector>
#include <unordered_set>
#include <string>

bool exploreIsland(std::vector<std::vector<char>> grid, int row, int col, std::unordered_set<std::string> &visited) {
  bool rowInbounds = 0 <= row && row < grid.size();
  bool colInbounds = 0 <= col && col < grid[0].size();

  if (!rowInbounds || !colInbounds) {
    return false;
  }

  if (grid[row][col] == 'W') {
    return false;
  }

  std::string pos = std::to_string(row) + "," + std::to_string(col);
  if (visited.count(pos) > 0) {
    return false;
  }
  visited.insert(pos);

  exploreIsland(grid, row - 1, col, visited);
  exploreIsland(grid, row + 1, col, visited);
  exploreIsland(grid, row, col - 1, visited);
  exploreIsland(grid, row, col + 1, visited);
  return true;
}

int islandCount(std::vector<std::vector<char>> grid) {
  std::unordered_set<std::string> visited;
  int count = 0;
  for (int r = 0; r < grid.size(); r += 1) {
    for (int c = 0; c < grid[0].size(); c += 1) {
      if (exploreIsland(grid, r, c, visited)) {
        count += 1;
      }
    }
  }

  return count;
}
```

- r = number of rows
- c = number of columns
- Time: O(rc)
- Space: O(rc)
